sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    treatsIntegration(); //Call to the main function for initiating the Treats Integration

    function treatsIntegration() {
        try {
            var maxRetries = 3; //Max number of retries post the 1st attempt
            var retryCount = 0;
            var tokenValue = '';
            var successflag = false;
            var callGetToken = true; //Variable used to define when shall we need to refresh the Token.

            //Base64 encoding of the request body in the format accepted by TREATS
            var encodedPayload = gs.base64Encode(current.request_body);
            var requestBody = 'data=' + encodeURIComponent(encodedPayload);


            while (retryCount <= maxRetries && !successflag) {

                //Refresh the token only when the callGetToken flag is set to TRUE
                if (callGetToken) {
                    tokenValue = new x_hsb11_mss_coll_0.MSS_Collateral_Treats_Integration().getToken(); //Call to the script include to refresh the token for TREATS
                }

                //Checking if the token value was recieved from TREATS
                if (tokenValue) {

                    //Call to the script include to send the request body and recieve the 1b response from TREATS
                    var response = new x_hsb11_mss_coll_0.MSS_Collateral_Treats_Integration().callTradeInput(tokenValue, requestBody);
                    var responseCatchException = response.catchExceptionMessage;
                    var responseStatusCode = response.tradeCallStatusCode;

                    if (responseCatchException == '') { //Checking if no exceptions caught in callTradeInput()
                        if (responseStatusCode) { //Checking if callTradeInput() has returned any responsecode/errorcode
                            switch (responseStatusCode) {
                                case 200:
                                    current.response_body = response.tradeCallResponseBody;
                                    current.error_code = responseStatusCode;
                                    current.response_date = new GlideDateTime();
                                    current.retry_count = retryCount;
                                    current.state = "Processed";
                                    successflag = true; //Setting the successflag to TRUE to come out of the while loop
                                    break;

                                case 400:
                                case 429:
                                    current.error_body = response.tradeCallResponseBody;
                                    current.error_code = responseStatusCode;
                                    //current.response_message = response.errorMessage;
                                    current.response_date = new GlideDateTime();
                                    current.retry_count = retryCount;
                                    current.state = "Error";
                                    successflag = true; //Setting the successflag to TRUE to come out of the while loop
                                    break;

                                case 401:
                                    current.error_body = response.tradeCallResponseBody;
                                    current.error_code = responseStatusCode;
                                    //current.response_message = response.errorMessage;
                                    current.response_date = new GlideDateTime();
                                    current.retry_count = retryCount;
                                    current.state = "Error";
                                    retryCount += 1;
                                    callGetToken = true; //Refreshing the token in case of error 401 i.e. Authentication Failed
                                    break;

                                case 500:
                                    current.error_body = response.tradeCallResponseBody;
                                    current.error_code = responseStatusCode;
                                    //current.response_message = response.errorMessage;
                                    current.response_date = new GlideDateTime();
                                    current.retry_count = retryCount;
                                    current.state = "Error";
                                    retryCount += 1;
                                    callGetToken = false; //No refresh of the token in case of error 500
                                    break;
                            }
                        } else {
                            //Setting the MSS Event Outbound record to ERROR after 3 attempts, if no response received from TREATS
                            current.error_body = "No response received from TREATS";
                            current.error_code = "NEC"; //No Error Code
                            //current.response_message = "No response received from TREATS";
                            current.response_date = new GlideDateTime();
                            current.retry_count = retryCount;
                            current.state = "Error";
                            retryCount += 1;
                            callGetToken = false;
                        }
                    } else {
                        //Setting the MSS Event Outbound record to ERROR, if any exception caught in the callTradeInput()
                        current.error_body = "Exception caught while receiving 1b response from TREATS";
                        current.error_code = "CE1B"; //Caught Exception for 1B response
                        //current.response_message = "Exception caught while receiving 1b response from TREATS";
                        current.response_date = new GlideDateTime();
                        current.retry_count = retryCount;
                        current.state = "Error";
                        break;
                    }
                } else {
                    //Setting the MSS Event Outbound record to ERROR after 3 attempts, if the token received is empty
                    current.error_body = "Error while trying to fetch the token from TREATS";
                    current.error_code = "NTR"; //No Token Received
                    //current.response_message = "Error while trying to fetch the token from TREATS";
                    current.response_date = new GlideDateTime();
                    current.retry_count = retryCount;
                    current.state = "Error";
                    retryCount += 1;
                    callGetToken = true;
                }
            }
            current.update();
        } catch (ex) {
            //Setting the MSS Event Outbound record to ERROR, if any exception caught in the treatsIntegration()
            current.error_body = "Error while trying to fetch the token and the 1b response from TREATS: "+ex.message;
            current.error_code = "CE1B"; //Caught Exception for 1B response
            //current.response_message = "Exception caught while receiving 1b response from TREATS";
            current.response_date = new GlideDateTime();
            current.retry_count = retryCount;
            current.state = "Error";
            current.update();
        }
    }
})(current, previous);
